const [shown, setShown] = useState(PAGE)

<Stack gap={1}>
  {Array.from({ length: shown }, (_, i) => (
    <ListItem key={i}>Update {i + 1}</ListItem>
  ))}
  {/* hasMore false renders nothing at all, so the end of the feed is quiet. */}
  <LoadMore
    hasMore={shown < TOTAL}
    label="Load more"
    onLoad={() => { setShown((n) => n + PAGE) }}
  />
</Stack>
